  const triFig = x => { const A = [0, 0], B = [x.ri(5, 8), 0], C = [x.ri(1, 4), x.ri(3, 5)]; return { A, B, C, fig: { type: 'geo', pts: { A, B, C }, segs: [['A', 'B'], ['B', 'C'], ['C', 'A']] } }; };
