    if (lv < 3) return { q: `حل المعادلة: $x^2 = ${a}$${lv === 2 ? ` ثم $${n === 1 ? '' : n}x^2 - ${n * n * n * 4} = 0$` : ''}`, s: [sol, lv === 2 ? `$x^2 = ${4 * n * n}$ ومنه $x = ${2 * n}$ أو $x = -${2 * n}$` : ''].filter(Boolean), chk: { js: `${a}>0?2:${a}===0?1:0`, out: a > 0 ? 2 : a === 0 ? 1 : 0 } };
